add_action( 'wp_login', static function ( $login, $user ) { update_user_meta( $user->ID, 'codeslot_last_login', time() ); }, 10, 2 );
add_filter( 'manage_users_columns', static function ( $columns ) { $columns['codeslot_last_login'] = 'Last login'; return $columns; } );
add_filter( 'manage_users_custom_column', static function ( $value, $column, $id ) { if ( 'codeslot_last_login' !== $column ) { return $value; } $time = (int) get_user_meta( $id, 'codeslot_last_login', true ); return $time ? wp_date( 'Y-m-d H:i', $time ) : 'Not recorded'; }, 10, 3 );
